-- EXPLAIN of MERGE where a relation has an index the join cannot use, or
-- one on the hashed relation's keys alone, which PostgreSQL's hash join
-- does not read; a unique one makes the hashed relation unique for the
-- join (Inner Unique).
CREATE TABLE t653 (id int, v int, x text);
INSERT INTO t653 SELECT g, g, 'x' || g FROM generate_series(1, 1000) g;
CREATE INDEX t653_v ON t653 (v);
CREATE TABLE s653 (k int PRIMARY KEY, w int);
INSERT INTO s653 SELECT g * 7, g FROM generate_series(1, 40) g;
CREATE INDEX s653_w ON s653 (w);
CREATE TABLE u653 (k int, w int UNIQUE);
INSERT INTO u653 SELECT g * 7, g FROM generate_series(1, 40) g;
ANALYZE t653;
ANALYZE s653;
ANALYZE u653;
EXPLAIN (COSTS OFF) MERGE INTO t653 USING u653 ON t653.id = u653.k
  WHEN MATCHED THEN UPDATE SET v = u653.w;
EXPLAIN (COSTS OFF) MERGE INTO t653 USING u653 ON t653.id = u653.k
  WHEN NOT MATCHED THEN INSERT VALUES (u653.k, u653.w);
EXPLAIN (COSTS OFF) MERGE INTO t653 USING s653 ON t653.id = s653.k
  WHEN MATCHED THEN UPDATE SET v = s653.w;
EXPLAIN (COSTS OFF, FORMAT JSON) MERGE INTO t653 USING s653 ON t653.id = s653.k
  WHEN MATCHED THEN UPDATE SET v = s653.w;
EXPLAIN (COSTS OFF, FORMAT JSON) MERGE INTO t653 USING u653 ON t653.id = u653.k
  WHEN MATCHED THEN UPDATE SET v = u653.w;
EXPLAIN (COSTS OFF) MERGE INTO s653 USING t653 ON t653.id = s653.k
  WHEN MATCHED THEN UPDATE SET w = t653.v;
EXPLAIN (VERBOSE, COSTS OFF) MERGE INTO t653 USING s653 ON t653.id = s653.k
  WHEN MATCHED THEN UPDATE SET v = s653.w WHEN NOT MATCHED THEN INSERT VALUES (s653.k, s653.w);
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t653 USING u653 ON t653.id = u653.k
  WHEN MATCHED THEN UPDATE SET v = u653.w WHEN NOT MATCHED THEN INSERT VALUES (u653.k, u653.w);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t653 USING s653 ON t653.id = s653.k
  WHEN MATCHED AND s653.w > 30 THEN DELETE;
ROLLBACK;
